function createSelector(inputSelector, resultFn) {
  let lastInput, lastResult;
  return function(state) {
    const input = inputSelector(state);
    if (input === lastInput) return lastResult;
    lastInput = input;
    lastResult = resultFn(input);
    return lastResult;
  };
}

