class FSM {
  constructor(initial, transitions) {
    this.state = initial;
    this.transitions = transitions;
  }
  dispatch(event) {
    const next = this.transitions[this.state]?.[event];
    if (!next) throw new Error(`Invalid transition: ${this.state} + ${event}`);
    this.state = next;
    return this.state;
  }
}

