class PubSub {
  constructor() { this._subs = {}; }
  subscribe(topic, fn) {
    (this._subs[topic] ??= []).push(fn);
    return () => this._subs[topic] = this._subs[topic].filter(f => f !== fn);
  }
  publish(topic, data) {
    (this._subs[topic] ?? []).forEach(fn => fn(data));
  }
}

