class Computed {
  constructor(fn) { this._fn = fn; this._dirty = true; }
  invalidate() { this._dirty = true; }
  get value() {
    if (this._dirty) {
      this._cached = this._fn();
      this._dirty = false;
    }
    return this._cached;
  }
}

