function update(obj, path, value) {
  const keys = path.split('.');
  if (keys.length === 1) return { ...obj, [path]: value };
  const [first, ...rest] = keys;
  return { ...obj, [first]: update(obj[first] ?? {}, rest.join('.'), value) };
}

