class UndoRedo {
  constructor(init) {
    this._history = [init];
    this._index = 0;
  }
  get current() { return this._history[this._index]; }
  push(state) {
    this._history = this._history.slice(0, this._index + 1);
    this._history.push(state);
    this._index++;
  }
  undo() { if (this._index > 0) this._index--; }
  redo() { if (this._index < this._history.length - 1) this._index++; }
}

